CREATE OR REPLACE FUNCTION public.check_zakat_conversion_pair_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_linked RECORD;
BEGIN
    IF NEW.entry_type = 'CONVERSION' THEN
        SELECT * INTO v_linked
        FROM public.zakat_wealth_entries
        WHERE id = NEW.linked_entry_id;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Conversion entry % references nonexistent linked_entry_id %', 
                NEW.id, NEW.linked_entry_id;
        END IF;

        IF v_linked.entry_type != 'CONVERSION' THEN
            RAISE EXCEPTION 'Conversion entry % is linked to non-conversion entry % (type: %)', 
                NEW.id, v_linked.id, v_linked.entry_type;
        END IF;

        IF v_linked.user_id != NEW.user_id THEN
            RAISE EXCEPTION 'Cross-user conversion pair prohibited: entry % (user %) -> entry % (user %)',
                NEW.id, NEW.user_id, v_linked.id, v_linked.user_id;
        END IF;

        IF v_linked.linked_entry_id != NEW.id THEN
            RAISE EXCEPTION 'Asymmetric conversion link: entry % points to %, but % points to %',
                NEW.id, NEW.linked_entry_id, v_linked.id, v_linked.linked_entry_id;
        END IF;

        IF round(NEW.amount_inr + v_linked.amount_inr, 2) != 0.00 THEN
            RAISE EXCEPTION 'Conversion monetary imbalance: leg % (%) and leg % (%) do not sum to 0',
                NEW.id, NEW.amount_inr, v_linked.id, v_linked.amount_inr;
        END IF;

        IF NEW.entry_date != v_linked.entry_date THEN
            RAISE EXCEPTION 'Conversion date mismatch: leg % date (%) != leg % date (%)',
                NEW.id, NEW.entry_date, v_linked.id, v_linked.entry_date;
        END IF;

        IF NEW.category = v_linked.category THEN
            RAISE EXCEPTION 'Conversion category circularity: source and destination categories are identical (%)',
                NEW.category;
        END IF;
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_zakat_paired_conversion(p_date date, p_source_category text, p_dest_category text, p_amount_inr numeric, p_source text DEFAULT 'Asset Conversion'::text, p_description text DEFAULT 'Asset Conversion'::text, p_source_quantity numeric DEFAULT NULL::numeric, p_source_purity_carat numeric DEFAULT NULL::numeric, p_dest_quantity numeric DEFAULT NULL::numeric, p_dest_purity_carat numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_user_id UUID;
    v_source_id UUID := gen_random_uuid();
    v_dest_id UUID := gen_random_uuid();
    v_abs_amount NUMERIC;
BEGIN
    -- 1. Authorization check: derive user strictly from trusted auth context
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Authentication required to create conversion entries';
    END IF;

    -- 2. Input validation
    IF p_date IS NULL THEN
        RAISE EXCEPTION 'Conversion date is required';
    END IF;

    IF p_amount_inr IS NULL OR p_amount_inr <= 0 THEN
        RAISE EXCEPTION 'Conversion amount must be a positive number';
    END IF;
    v_abs_amount := round(p_amount_inr, 2);

    IF p_source_category = p_dest_category THEN
        RAISE EXCEPTION 'Source and destination categories must differ';
    END IF;

    -- Restrict conversion categories strictly to eligible asset pools
    IF p_source_category NOT IN (
        'CASH', 'BANK', 'DIGITAL_WALLET', 'GOLD', 'SILVER',
        'BUSINESS_INVENTORY', 'INVESTMENTS',
        'RECEIVABLES_STRONG', 'OTHER_ASSET'
    ) THEN
        RAISE EXCEPTION 'Invalid or non-convertible source category: %', p_source_category
            USING ERRCODE = 'check_violation';
    END IF;

    IF p_dest_category NOT IN (
        'CASH', 'BANK', 'DIGITAL_WALLET', 'GOLD', 'SILVER',
        'BUSINESS_INVENTORY', 'INVESTMENTS',
        'RECEIVABLES_STRONG', 'OTHER_ASSET'
    ) THEN
        RAISE EXCEPTION 'Invalid or non-convertible destination category: %', p_dest_category
            USING ERRCODE = 'check_violation';
    END IF;

    -- Metal field validation
    IF p_source_category NOT IN ('GOLD', 'SILVER') AND (p_source_quantity IS NOT NULL OR p_source_purity_carat IS NOT NULL) THEN
        RAISE EXCEPTION 'Source category % cannot carry metal quantity or purity', p_source_category;
    END IF;

    IF p_dest_category NOT IN ('GOLD', 'SILVER') AND (p_dest_quantity IS NOT NULL OR p_dest_purity_carat IS NOT NULL) THEN
        RAISE EXCEPTION 'Destination category % cannot carry metal quantity or purity', p_dest_category;
    END IF;

    IF p_source_purity_carat IS NOT NULL AND (p_source_purity_carat < 1.0 OR p_source_purity_carat > 24.0) THEN
        RAISE EXCEPTION 'Source purity carat must be between 1.0 and 24.0 (received: %)', p_source_purity_carat
            USING ERRCODE = 'check_violation';
    END IF;

    IF p_dest_purity_carat IS NOT NULL AND (p_dest_purity_carat < 1.0 OR p_dest_purity_carat > 24.0) THEN
        RAISE EXCEPTION 'Destination purity carat must be between 1.0 and 24.0 (received: %)', p_dest_purity_carat
            USING ERRCODE = 'check_violation';
    END IF;

    -- 3. Insert Outgoing Leg (Debit)
    INSERT INTO public.zakat_wealth_entries (
        id,
        user_id,
        entry_date,
        entry_type,
        category,
        source,
        amount_inr,
        quantity,
        purity_carat,
        linked_entry_id,
        description
    ) VALUES (
        v_source_id,
        v_user_id,
        p_date,
        'CONVERSION',
        p_source_category,
        COALESCE(NULLIF(TRIM(p_source), ''), 'Asset Conversion'),
        -v_abs_amount,
        CASE WHEN p_source_quantity IS NOT NULL THEN -ABS(p_source_quantity) ELSE NULL END,
        p_source_purity_carat,
        v_dest_id,
        '[Conversion Out] ' || COALESCE(NULLIF(TRIM(p_description), ''), 'Asset Conversion')
    );

    -- 4. Insert Incoming Leg (Credit)
    INSERT INTO public.zakat_wealth_entries (
        id,
        user_id,
        entry_date,
        entry_type,
        category,
        source,
        amount_inr,
        quantity,
        purity_carat,
        linked_entry_id,
        description
    ) VALUES (
        v_dest_id,
        v_user_id,
        p_date,
        'CONVERSION',
        p_dest_category,
        COALESCE(NULLIF(TRIM(p_source), ''), 'Asset Conversion'),
        v_abs_amount,
        CASE WHEN p_dest_quantity IS NOT NULL THEN ABS(p_dest_quantity) ELSE NULL END,
        p_dest_purity_carat,
        v_source_id,
        '[Conversion In] ' || COALESCE(NULLIF(TRIM(p_description), ''), 'Asset Conversion')
    );

    RETURN jsonb_build_object(
        'source_entry_id', v_source_id,
        'dest_entry_id', v_dest_id,
        'amount_inr', v_abs_amount,
        'entry_date', p_date
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_zakat_paired_conversion(p_entry_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_user_id UUID;
    v_entry RECORD;
    v_linked RECORD;
BEGIN
    -- 1. Authorization check: derive user strictly from trusted auth context
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Authentication required to delete conversion entries';
    END IF;

    -- 2. Fetch targeted entry
    SELECT * INTO v_entry
    FROM public.zakat_wealth_entries
    WHERE id = p_entry_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Conversion entry % not found', p_entry_id;
    END IF;

    -- 3. Strict ownership check
    IF v_entry.user_id != v_user_id THEN
        RAISE EXCEPTION 'Access denied: cannot delete another user''s conversion entry';
    END IF;

    IF v_entry.entry_type != 'CONVERSION' THEN
        RAISE EXCEPTION 'Entry % is not a CONVERSION entry (type: %)', p_entry_id, v_entry.entry_type;
    END IF;

    IF v_entry.linked_entry_id IS NULL THEN
        RAISE EXCEPTION 'Conversion entry % has no linked counterpart', p_entry_id;
    END IF;

    -- 4. Fetch linked counterpart
    SELECT * INTO v_linked
    FROM public.zakat_wealth_entries
    WHERE id = v_entry.linked_entry_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Linked conversion partner % not found for entry %', v_entry.linked_entry_id, p_entry_id;
    END IF;

    IF v_linked.user_id != v_user_id THEN
        RAISE EXCEPTION 'Integrity violation: linked partner % belongs to another user', v_linked.id;
    END IF;

    -- 5. Deterministic row locking in ascending UUID order to prevent deadlocks
    PERFORM id 
    FROM public.zakat_wealth_entries 
    WHERE id IN (v_entry.id, v_linked.id)
    ORDER BY id ASC
    FOR UPDATE;

    -- 6. Atomic deletion of both legs in single statement
    DELETE FROM public.zakat_wealth_entries
    WHERE id IN (v_entry.id, v_linked.id);

    RETURN jsonb_build_object(
        'deleted_entry_id', v_entry.id,
        'deleted_linked_id', v_linked.id,
        'status', 'DELETED'
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_naeem_opening_balance(p_year integer, p_month integer)
 RETURNS TABLE(opening_balance numeric, is_manual_override boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_manual_year INT;
    v_manual_month INT;
    v_manual_balance NUMERIC := 0;
    v_start_date DATE;
    v_end_date DATE;
    v_total_billed NUMERIC := 0;
    v_total_received NUMERIC := 0;
    v_target_date DATE;
    v_row_exists BOOLEAN;
BEGIN
    SELECT nmb.opening_balance, nmb.is_manual_override 
    INTO v_manual_balance, v_row_exists
    FROM public.naeem_monthly_balances nmb
    WHERE nmb.year = p_year AND nmb.month = p_month AND nmb.is_manual_override = TRUE;
    
    IF FOUND THEN
        RETURN QUERY SELECT v_manual_balance, TRUE;
        RETURN;
    END IF;

    SELECT nmb.year, nmb.month, nmb.opening_balance
    INTO v_manual_year, v_manual_month, v_manual_balance
    FROM public.naeem_monthly_balances nmb
    WHERE (nmb.year < p_year OR (nmb.year = p_year AND nmb.month < p_month))
      AND nmb.is_manual_override = TRUE
    ORDER BY nmb.year DESC, nmb.month DESC
    LIMIT 1;

    IF FOUND THEN
        v_start_date := make_date(v_manual_year, v_manual_month, 1);
    ELSE
        v_start_date := '2000-01-01'::DATE;
        v_manual_balance := 0;
    END IF;

    v_target_date := make_date(p_year, p_month, 1);
    v_end_date := v_target_date - INTERVAL '1 day';

    SELECT COALESCE(SUM(r.final_fare), 0)
    INTO v_total_billed
    FROM public.naeem_daily_records r
    LEFT JOIN public.naeem_routes rt ON r.route_id = rt.id
    WHERE r.delivery_date >= v_start_date AND r.delivery_date <= v_end_date
      AND r.status != 'No Order'
      AND LOWER(rt.name) != 'no order';

    SELECT COALESCE(SUM(p.amount), 0)
    INTO v_total_received
    FROM public.naeem_payments p
    WHERE p.payment_date >= v_start_date AND p.payment_date <= v_end_date;

    RETURN QUERY SELECT (v_manual_balance + v_total_billed - v_total_received), FALSE;
END;
$function$

CREATE OR REPLACE FUNCTION public.naeem_set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at := NOW();
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.protect_zakat_ledger_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_parent_user_id UUID;
BEGIN
    -- Detect any attempt to alter financial, structural, or ownership fields
    IF OLD.amount_inr IS DISTINCT FROM NEW.amount_inr
       OR OLD.entry_date IS DISTINCT FROM NEW.entry_date
       OR OLD.category IS DISTINCT FROM NEW.category
       OR OLD.entry_type IS DISTINCT FROM NEW.entry_type
       OR OLD.quantity IS DISTINCT FROM NEW.quantity
       OR OLD.purity_carat IS DISTINCT FROM NEW.purity_carat
       OR OLD.linked_entry_id IS DISTINCT FROM NEW.linked_entry_id
       OR OLD.user_id IS DISTINCT FROM NEW.user_id
       OR OLD.correction_of_entry_id IS DISTINCT FROM NEW.correction_of_entry_id
    THEN
        RAISE EXCEPTION 'Financial ledger fields are strictly immutable. Post a CORRECTION entry for ledger adjustments.'
            USING ERRCODE = 'restrict_violation';
    END IF;

    -- Validate same-user boundary on correction reference
    IF NEW.correction_of_entry_id IS NOT NULL THEN
        SELECT user_id INTO v_parent_user_id 
        FROM public.zakat_wealth_entries 
        WHERE id = NEW.correction_of_entry_id;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Target corrected entry % does not exist', NEW.correction_of_entry_id;
        END IF;

        IF v_parent_user_id != NEW.user_id THEN
            RAISE EXCEPTION 'Cross-user correction prohibited: entry % belongs to another user', NEW.correction_of_entry_id;
        END IF;
    END IF;

    NEW.updated_at := NOW();
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.record_customer_payment_with_allocations(p_customer_id uuid, p_amount numeric, p_payment_date date, p_payment_method text DEFAULT 'Cash'::text, p_reference text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_allocations jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_payment_id UUID;
    v_alloc JSONB;
    v_credit_id UUID;
    v_alloc_amount NUMERIC;
    v_alloc_notes TEXT;
    v_total_allocated NUMERIC := 0;
    v_credit_balance NUMERIC;
BEGIN
    -- 1. Authentication & Authorization check
    -- Note: inside a SECURITY DEFINER function, current_user evaluates to the function owner (postgres).
    -- We verify the calling session via Supabase JWT context: auth.role() and auth.uid().
    IF auth.role() = 'anon' OR (COALESCE(auth.role(), '') <> 'service_role' AND auth.uid() IS NULL) THEN
        RAISE EXCEPTION 'Authentication required to record customer payment';
    END IF;

    -- 2. Input validation
    IF p_customer_id IS NULL THEN
        RAISE EXCEPTION 'Customer ID is required';
    END IF;

    IF p_amount IS NULL OR p_amount <= 0 THEN
        RAISE EXCEPTION 'Payment amount must be greater than zero';
    END IF;

    IF NOT EXISTS (SELECT 1 FROM reseller_customers WHERE id = p_customer_id) THEN
        RAISE EXCEPTION 'Customer % does not exist', p_customer_id;
    END IF;

    -- 3. Idempotency & duplicate submission guard
    -- Differentiate unique transaction identifiers (cheques/UTRs) from generic payment method notes (e.g., 'Cash', 'Bank')
    IF p_reference IS NOT NULL AND TRIM(p_reference) <> '' THEN
        IF LOWER(TRIM(p_reference)) IN ('cash', 'bank', 'online', 'cheque', 'check', 'upi', 'hand cash', 'advance', 'payment', 'transfer', 'deposit', 'paid') THEN
            -- Generic reference: allow reuse across different dates/amounts, but reject exact identical duplicate on the same date
            IF EXISTS (
                SELECT 1 FROM reseller_payments 
                WHERE customer_id = p_customer_id 
                  AND amount = p_amount
                  AND payment_date = COALESCE(p_payment_date, CURRENT_DATE)
                  AND LOWER(TRIM(reference)) = LOWER(TRIM(p_reference))
            ) THEN
                RAISE EXCEPTION 'Duplicate payment of % with reference % on % already recorded for customer %', 
                    p_amount, TRIM(p_reference), COALESCE(p_payment_date, CURRENT_DATE), p_customer_id;
            END IF;
        ELSE
            -- Specific transaction reference (e.g. cheque number or UTR): enforce unique reference per customer
            IF EXISTS (
                SELECT 1 FROM reseller_payments 
                WHERE customer_id = p_customer_id 
                  AND reference = TRIM(p_reference)
            ) THEN
                RAISE EXCEPTION 'Payment with reference % already exists for customer %', TRIM(p_reference), p_customer_id;
            END IF;
        END IF;
    END IF;

    -- Guard against accidental double-clicks within a 3-second window
    IF EXISTS (
        SELECT 1 FROM reseller_payments 
        WHERE customer_id = p_customer_id 
          AND amount = p_amount 
          AND payment_date = COALESCE(p_payment_date, CURRENT_DATE)
          AND created_at >= (NOW() - INTERVAL '3 seconds')
    ) THEN
        RAISE EXCEPTION 'Duplicate payment request detected within last 3 seconds. Please refresh before retrying.';
    END IF;

    -- 4. Validate allocations sum before performing any inserts
    IF p_allocations IS NOT NULL AND jsonb_array_length(p_allocations) > 0 THEN
        FOR v_alloc IN SELECT * FROM jsonb_array_elements(p_allocations)
        LOOP
            v_alloc_amount := (v_alloc->>'amount')::NUMERIC;
            IF v_alloc_amount > 0 THEN
                v_total_allocated := v_total_allocated + v_alloc_amount;
            END IF;
        END LOOP;

        IF v_total_allocated > (p_amount + 0.001) THEN
            RAISE EXCEPTION 'Total allocated amount (%) cannot exceed payment amount (%)', v_total_allocated, p_amount;
        END IF;
    END IF;

    -- 5. Insert into reseller_payments
    INSERT INTO reseller_payments (
        customer_id,
        payment_date,
        amount,
        payment_method,
        reference,
        notes
    )
    VALUES (
        p_customer_id,
        COALESCE(p_payment_date, CURRENT_DATE),
        p_amount,
        COALESCE(p_payment_method, 'Cash'),
        NULLIF(TRIM(p_reference), ''),
        NULLIF(TRIM(p_notes), '')
    )
    RETURNING id INTO v_payment_id;

    -- 6. Process and insert individual allocations with balance bounds check
    IF p_allocations IS NOT NULL AND jsonb_array_length(p_allocations) > 0 THEN
        -- Acquire row-level locks on all targeted customer credits in deterministic ascending UUID order.
        -- This guarantees consistent lock acquisition order across concurrent transactions, eliminating deadlock risk.
        PERFORM id 
        FROM customer_credits 
        WHERE customer_id = p_customer_id 
          AND id IN (
              SELECT (x->>'credit_id')::UUID 
              FROM jsonb_array_elements(p_allocations) x 
              WHERE (x->>'amount')::NUMERIC > 0
          )
        ORDER BY id
        FOR UPDATE;

        FOR v_alloc IN SELECT * FROM jsonb_array_elements(p_allocations)
        LOOP
            v_credit_id := (v_alloc->>'credit_id')::UUID;
            v_alloc_amount := (v_alloc->>'amount')::NUMERIC;
            v_alloc_notes := NULLIF(TRIM(v_alloc->>'notes'), '');

            IF v_alloc_amount > 0 THEN
                -- Validate credit ownership and remaining balance (already locked above)
                SELECT balance INTO v_credit_balance 
                FROM customer_credits 
                WHERE id = v_credit_id AND customer_id = p_customer_id
                FOR UPDATE;

                IF NOT FOUND THEN
                    RAISE EXCEPTION 'Target credit entry % does not exist or does not belong to customer %', v_credit_id, p_customer_id;
                END IF;

                IF v_alloc_amount > (v_credit_balance + 0.001) THEN
                    RAISE EXCEPTION 'Allocation amount (%) exceeds remaining balance (%) for credit %', v_alloc_amount, v_credit_balance, v_credit_id;
                END IF;

                -- Insert allocation (triggers trg_sync_customer_credit_balance automatically)
                INSERT INTO customer_payment_allocations (
                    payment_id,
                    credit_id,
                    amount,
                    notes
                )
                VALUES (
                    v_payment_id,
                    v_credit_id,
                    v_alloc_amount,
                    v_alloc_notes
                );
            END IF;
        END LOOP;
    END IF;

    -- 7. Return committed transaction metadata
    RETURN jsonb_build_object(
        'payment_id', v_payment_id,
        'total_amount', p_amount,
        'allocated_amount', v_total_allocated,
        'advance_amount', GREATEST(0, p_amount - v_total_allocated)
    );
EXCEPTION WHEN OTHERS THEN
    -- Automatic PostgreSQL transaction rollback guarantees zero partial rows
    RAISE;
END;
$function$

CREATE OR REPLACE FUNCTION public.resolve_delivery_entry_workspace()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_user_id UUID;
    v_is_super_admin BOOLEAN := false;
    v_is_user_active BOOLEAN := false;
    v_parent_workspace_id UUID;
BEGIN
    v_user_id := auth.uid();

    -- Service role / background system maintenance (auth.uid() IS NULL)
    IF v_user_id IS NULL THEN
        IF NEW.workspace_id IS NOT NULL THEN
            RETURN NEW;
        END IF;
    END IF;

    -- Inherit from parent daily record
    IF NEW.daily_record_id IS NOT NULL THEN
        SELECT workspace_id INTO v_parent_workspace_id
        FROM public.general_daily_records
        WHERE id = NEW.daily_record_id;

        IF v_parent_workspace_id IS NULL THEN
            RAISE EXCEPTION 'Parent daily record not found: daily_record_id % does not exist.', NEW.daily_record_id
                USING ERRCODE = '42501';
        END IF;

        IF NEW.workspace_id IS NOT NULL AND NEW.workspace_id <> v_parent_workspace_id THEN
            RAISE EXCEPTION 'Parent-child workspace mismatch: general_delivery_entries workspace must match daily record workspace.'
                USING ERRCODE = '42501';
        END IF;

        NEW.workspace_id := v_parent_workspace_id;
    ELSE
        RAISE EXCEPTION 'daily_record_id is required for general delivery entries.'
            USING ERRCODE = '42501';
    END IF;

    -- Verify caller profile is active and has access to parent workspace
    IF v_user_id IS NOT NULL THEN
        SELECT is_active, (system_role = 'SUPER_ADMIN')
        INTO v_is_user_active, v_is_super_admin
        FROM public.profiles
        WHERE id = v_user_id;

        IF v_is_user_active IS NOT TRUE THEN
            RAISE EXCEPTION 'Account suspended: active account required for delivery operations.'
                USING ERRCODE = '42501';
        END IF;

        IF NOT v_is_super_admin THEN
            IF NOT EXISTS (
                SELECT 1 FROM public.workspace_members wm
                WHERE wm.workspace_id = NEW.workspace_id
                  AND wm.user_id = v_user_id
                  AND wm.is_active = true
            ) THEN
                RAISE EXCEPTION 'Unauthorized workspace: caller is not an active member of workspace %.', NEW.workspace_id
                    USING ERRCODE = '42501';
            END IF;
        END IF;
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.resolve_delivery_workspace()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_user_id UUID;
    v_is_super_admin BOOLEAN := false;
    v_is_user_active BOOLEAN := false;
    v_ws_type TEXT;
    v_ws_active BOOLEAN;
    v_matched_count INT;
    v_resolved_ws_id UUID;
BEGIN
    v_user_id := auth.uid();

    -- Service role / background system maintenance (auth.uid() IS NULL)
    IF v_user_id IS NULL THEN
        IF NEW.workspace_id IS NOT NULL THEN
            RETURN NEW;
        ELSE
            RAISE EXCEPTION 'Authentication required: caller identity cannot be verified and no workspace_id provided.'
                USING ERRCODE = '42501';
        END IF;
    END IF;

    -- 1. Verify caller profile exists and is active
    SELECT is_active, (system_role = 'SUPER_ADMIN')
    INTO v_is_user_active, v_is_super_admin
    FROM public.profiles
    WHERE id = v_user_id;

    IF v_is_user_active IS NOT TRUE THEN
        RAISE EXCEPTION 'Account suspended: active account required for delivery operations.'
            USING ERRCODE = '42501';
    END IF;

    -- 2. Case A: Client provided an explicit workspace_id
    IF NEW.workspace_id IS NOT NULL THEN
        -- Never trust client-provided workspace ID without validating membership
        SELECT workspace_type, is_active
        INTO v_ws_type, v_ws_active
        FROM public.workspaces
        WHERE id = NEW.workspace_id;

        IF v_ws_type IS NULL THEN
            RAISE EXCEPTION 'Invalid workspace: specified workspace does not exist.'
                USING ERRCODE = '42501';
        END IF;

        IF v_ws_active IS NOT TRUE THEN
            RAISE EXCEPTION 'Workspace inactive: cannot insert delivery records into a deactivated workspace.'
                USING ERRCODE = '42501';
        END IF;

        IF v_ws_type <> 'BUSINESS' THEN
            RAISE EXCEPTION 'Invalid workspace type: delivery operations are restricted to business workspaces.'
                USING ERRCODE = '42501';
        END IF;

        -- Verify membership unless caller is super admin
        IF NOT v_is_super_admin THEN
            IF NOT EXISTS (
                SELECT 1 FROM public.workspace_members wm
                WHERE wm.workspace_id = NEW.workspace_id
                  AND wm.user_id = v_user_id
                  AND wm.is_active = true
            ) THEN
                RAISE EXCEPTION 'Unauthorized workspace: caller is not an active member of workspace %.', NEW.workspace_id
                    USING ERRCODE = '42501';
            END IF;
        END IF;

        RETURN NEW;
    END IF;

    -- 3. Case B: Client did NOT provide workspace_id (NEW.workspace_id IS NULL)
    -- Resolve from verified, active business workspace memberships
    SELECT COUNT(DISTINCT w.id)
    INTO v_matched_count
    FROM public.workspaces w
    JOIN public.workspace_members wm ON wm.workspace_id = w.id
    WHERE wm.user_id = v_user_id
      AND wm.is_active = true
      AND w.is_active = true
      AND w.workspace_type = 'BUSINESS';

    -- If user has no active business workspace memberships:
    IF v_matched_count = 0 THEN
        RAISE EXCEPTION 'No authorized business workspace: caller is not an active member of any business workspace.'
            USING ERRCODE = '42501';
    END IF;

    -- If user belongs to multiple active business workspaces, reject ambiguity:
    IF v_matched_count > 1 THEN
        RAISE EXCEPTION 'Ambiguous workspace membership: caller belongs to multiple active business workspaces. Explicit workspace_id is required.'
            USING ERRCODE = '42501';
    END IF;

    -- Exactly 1 active business workspace: unambiguous resolution
    SELECT w.id
    INTO v_resolved_ws_id
    FROM public.workspaces w
    JOIN public.workspace_members wm ON wm.workspace_id = w.id
    WHERE wm.user_id = v_user_id
      AND wm.is_active = true
      AND w.is_active = true
      AND w.workspace_type = 'BUSINESS'
    LIMIT 1;

    NEW.workspace_id := v_resolved_ws_id;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.resolve_naeem_allocation_workspace()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_user_id UUID;
    v_is_super_admin BOOLEAN := false;
    v_is_user_active BOOLEAN := false;
    v_payment_ws_id UUID;
    v_daily_record_ws_id UUID;
BEGIN
    v_user_id := auth.uid();

    -- Service role / background system maintenance (auth.uid() IS NULL)
    IF v_user_id IS NULL THEN
        IF NEW.workspace_id IS NOT NULL THEN
            RETURN NEW;
        END IF;
    END IF;

    -- Look up payment's workspace
    IF NEW.payment_id IS NOT NULL THEN
        SELECT workspace_id INTO v_payment_ws_id
        FROM public.naeem_payments
        WHERE id = NEW.payment_id;

        IF v_payment_ws_id IS NULL THEN
            RAISE EXCEPTION 'Parent payment not found: payment_id % does not exist.', NEW.payment_id
                USING ERRCODE = '42501';
        END IF;
    END IF;

    -- Look up daily record's workspace
    IF NEW.daily_record_id IS NOT NULL THEN
        SELECT workspace_id INTO v_daily_record_ws_id
        FROM public.naeem_daily_records
        WHERE id = NEW.daily_record_id;

        IF v_daily_record_ws_id IS NULL THEN
            RAISE EXCEPTION 'Parent daily record not found: daily_record_id % does not exist.', NEW.daily_record_id
                USING ERRCODE = '42501';
        END IF;
    END IF;

    -- Verify payment and daily record belong to the same workspace
    IF v_payment_ws_id IS NOT NULL AND v_daily_record_ws_id IS NOT NULL THEN
        IF v_payment_ws_id <> v_daily_record_ws_id THEN
            RAISE EXCEPTION 'Parent-child workspace mismatch: payment workspace (%) does not match daily record workspace (%).',
                v_payment_ws_id, v_daily_record_ws_id
                USING ERRCODE = '42501';
        END IF;
    END IF;

    -- If client passed workspace_id, verify it matches
    IF NEW.workspace_id IS NOT NULL THEN
        IF v_payment_ws_id IS NOT NULL AND NEW.workspace_id <> v_payment_ws_id THEN
            RAISE EXCEPTION 'Workspace mismatch: allocation workspace does not match payment workspace.'
                USING ERRCODE = '42501';
        END IF;
    ELSE
        NEW.workspace_id := COALESCE(v_payment_ws_id, v_daily_record_ws_id);
    END IF;

    IF NEW.workspace_id IS NULL THEN
        RAISE EXCEPTION 'Unable to resolve workspace for payment allocation.'
            USING ERRCODE = '42501';
    END IF;

    -- Verify caller profile is active and has access to this workspace
    IF v_user_id IS NOT NULL THEN
        SELECT is_active, (system_role = 'SUPER_ADMIN')
        INTO v_is_user_active, v_is_super_admin
        FROM public.profiles
        WHERE id = v_user_id;

        IF v_is_user_active IS NOT TRUE THEN
            RAISE EXCEPTION 'Account suspended: active account required for delivery operations.'
                USING ERRCODE = '42501';
        END IF;

        IF NOT v_is_super_admin THEN
            IF NOT EXISTS (
                SELECT 1 FROM public.workspace_members wm
                WHERE wm.workspace_id = NEW.workspace_id
                  AND wm.user_id = v_user_id
                  AND wm.is_active = true
            ) THEN
                RAISE EXCEPTION 'Unauthorized workspace: caller is not an active member of workspace %.', NEW.workspace_id
                    USING ERRCODE = '42501';
            END IF;
        END IF;
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.resolve_naeem_daily_record_workspace()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_user_id UUID;
    v_is_super_admin BOOLEAN := false;
    v_is_user_active BOOLEAN := false;
    v_route_workspace_id UUID;
    v_ws_type TEXT;
    v_ws_active BOOLEAN;
BEGIN
    v_user_id := auth.uid();

    -- Service role / background system maintenance (auth.uid() IS NULL)
    IF v_user_id IS NULL THEN
        IF NEW.workspace_id IS NOT NULL THEN
            RETURN NEW;
        END IF;
    END IF;

    -- 1. Validate route_id
    IF NEW.route_id IS NULL THEN
        RAISE EXCEPTION 'route_id is required for naeem daily delivery records.'
            USING ERRCODE = '42501';
    END IF;

    SELECT r.workspace_id, w.workspace_type, w.is_active
    INTO v_route_workspace_id, v_ws_type, v_ws_active
    FROM public.naeem_routes r
    JOIN public.workspaces w ON w.id = r.workspace_id
    WHERE r.id = NEW.route_id;

    IF v_route_workspace_id IS NULL THEN
        RAISE EXCEPTION 'Invalid route: specified route does not exist.'
            USING ERRCODE = '42501';
    END IF;

    IF v_ws_active IS NOT TRUE THEN
        RAISE EXCEPTION 'Workspace inactive: route belongs to an inactive workspace.'
            USING ERRCODE = '42501';
    END IF;

    IF v_ws_type <> 'BUSINESS' THEN
        RAISE EXCEPTION 'Invalid workspace type: route belongs to a non-business workspace.'
            USING ERRCODE = '42501';
    END IF;

    -- 2. Verify caller profile exists and is active
    IF v_user_id IS NOT NULL THEN
        SELECT is_active, (system_role = 'SUPER_ADMIN')
        INTO v_is_user_active, v_is_super_admin
        FROM public.profiles
        WHERE id = v_user_id;

        IF v_is_user_active IS NOT TRUE THEN
            RAISE EXCEPTION 'Account suspended: active account required for delivery operations.'
                USING ERRCODE = '42501';
        END IF;

        -- Verify caller has active membership in the route's workspace
        IF NOT v_is_super_admin THEN
            IF NOT EXISTS (
                SELECT 1 FROM public.workspace_members wm
                WHERE wm.workspace_id = v_route_workspace_id
                  AND wm.user_id = v_user_id
                  AND wm.is_active = true
            ) THEN
                RAISE EXCEPTION 'Unauthorized route: caller is not an active member of the route''s workspace.'
                    USING ERRCODE = '42501';
            END IF;
        END IF;
    END IF;

    -- 3. If caller supplied workspace_id, verify it matches route's workspace
    IF NEW.workspace_id IS NOT NULL AND NEW.workspace_id <> v_route_workspace_id THEN
        RAISE EXCEPTION 'Workspace mismatch: naeem_daily_records workspace (%) must match route workspace (%).',
            NEW.workspace_id, v_route_workspace_id
            USING ERRCODE = '42501';
    END IF;

    -- Inherit workspace_id directly from the verified route
    NEW.workspace_id := v_route_workspace_id;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_customer_credit_defaults()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.balance := GREATEST(0, NEW.total_amount - NEW.amount_paid);
    NEW.status := CASE 
        WHEN NEW.amount_paid >= NEW.total_amount THEN 'PAID'
        WHEN NEW.amount_paid > 0 THEN 'PARTIAL'
        ELSE 'PENDING'
    END;
    NEW.updated_at := NOW();
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_customer_credit_balance()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_credit_id UUID;
    v_total_allocated NUMERIC(12, 2);
    v_total_amount NUMERIC(12, 2);
BEGIN
    IF TG_OP = 'DELETE' THEN
        v_credit_id := OLD.credit_id;
    ELSE
        v_credit_id := NEW.credit_id;
    END IF;

    SELECT COALESCE(SUM(amount), 0) INTO v_total_allocated
    FROM public.customer_payment_allocations
    WHERE credit_id = v_credit_id;

    SELECT total_amount INTO v_total_amount
    FROM public.customer_credits
    WHERE id = v_credit_id;

    IF v_total_amount IS NOT NULL THEN
        UPDATE public.customer_credits
        SET 
            amount_paid = v_total_allocated,
            balance = GREATEST(0, v_total_amount - v_total_allocated),
            status = CASE 
                WHEN v_total_allocated >= v_total_amount THEN 'PAID'
                WHEN v_total_allocated > 0 THEN 'PARTIAL'
                ELSE 'PENDING'
            END,
            updated_at = NOW()
        WHERE id = v_credit_id;
    END IF;

    RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_stock_on_customer_credit()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.product_id IS NOT NULL AND NEW.quantity IS NOT NULL THEN
            UPDATE products SET stock_quantity = stock_quantity - NEW.quantity WHERE id = NEW.product_id;
        END IF;
    ELSIF TG_OP = 'UPDATE' THEN
        -- Revert old stock if product was linked
        IF OLD.product_id IS NOT NULL AND OLD.quantity IS NOT NULL THEN
            UPDATE products SET stock_quantity = stock_quantity + OLD.quantity WHERE id = OLD.product_id;
        END IF;
        -- Apply new stock if product is linked
        IF NEW.product_id IS NOT NULL AND NEW.quantity IS NOT NULL THEN
            UPDATE products SET stock_quantity = stock_quantity - NEW.quantity WHERE id = NEW.product_id;
        END IF;
    ELSIF TG_OP = 'DELETE' THEN
        IF OLD.product_id IS NOT NULL AND OLD.quantity IS NOT NULL THEN
            UPDATE products SET stock_quantity = stock_quantity + OLD.quantity WHERE id = OLD.product_id;
        END IF;
    END IF;
    RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_stock_on_sale()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'INSERT' THEN
        UPDATE products SET stock_quantity = stock_quantity - NEW.quantity WHERE id = NEW.product_id;
    ELSIF TG_OP = 'UPDATE' THEN
        UPDATE products SET stock_quantity = stock_quantity + OLD.quantity - NEW.quantity WHERE id = NEW.product_id;
    ELSIF TG_OP = 'DELETE' THEN
        UPDATE products SET stock_quantity = stock_quantity + OLD.quantity WHERE id = OLD.product_id;
    END IF;
    RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_naeem_daily_record_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_user_id UUID;
    v_is_super_admin BOOLEAN := false;
    v_is_user_active BOOLEAN := false;
    v_new_route_ws_id UUID;
BEGIN
    -- 1. Enforce workspace immutability
    IF OLD.workspace_id IS NOT NULL AND NEW.workspace_id IS DISTINCT FROM OLD.workspace_id THEN
        RAISE EXCEPTION 'Workspace immutability violation: workspace_id cannot be modified.'
            USING ERRCODE = '42501';
    END IF;

    -- 2. If route_id is modified, ensure the new route belongs to the same workspace
    IF NEW.route_id IS DISTINCT FROM OLD.route_id THEN
        SELECT workspace_id INTO v_new_route_ws_id
        FROM public.naeem_routes
        WHERE id = NEW.route_id;

        IF v_new_route_ws_id IS NULL THEN
            RAISE EXCEPTION 'Invalid route: new route does not exist.'
                USING ERRCODE = '42501';
        END IF;

        IF v_new_route_ws_id <> NEW.workspace_id THEN
            RAISE EXCEPTION 'Workspace route mismatch: cannot change route to a route belonging to a different workspace.'
                USING ERRCODE = '42501';
        END IF;

        -- Verify caller is active
        v_user_id := auth.uid();
        IF v_user_id IS NOT NULL THEN
            SELECT is_active, (system_role = 'SUPER_ADMIN')
            INTO v_is_user_active, v_is_super_admin
            FROM public.profiles
            WHERE id = v_user_id;

            IF v_is_user_active IS NOT TRUE THEN
                RAISE EXCEPTION 'Account suspended: active account required for delivery operations.'
                    USING ERRCODE = '42501';
            END IF;

            IF NOT v_is_super_admin THEN
                IF NOT EXISTS (
                    SELECT 1 FROM public.workspace_members wm
                    WHERE wm.workspace_id = NEW.workspace_id
                      AND wm.user_id = v_user_id
                      AND wm.is_active = true
                ) THEN
                    RAISE EXCEPTION 'Unauthorized workspace: caller is not an active member of workspace %.', NEW.workspace_id
                        USING ERRCODE = '42501';
                END IF;
            END IF;
        END IF;
    END IF;

    RETURN NEW;
END;
$function$
